return {
  ["unclaimed-dawn-court-4"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 10 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the Keeper clear of grounding volunteers."}}, {id = "healer", label = "Healers", tips = {"Heal the marked volunteer after a failed future check."}}, {id = "damage", label = "Damage dealers", tips = {"Expose and destroy or control both contingency crystals."}}, {id = "everyone", label = "Everyone", tips = {"Grounding stones need four seconds of occupancy; crystals become exposed after one failed check."}}}, phases = {{label = "Break the contingency", trigger = "At 75%, 45% and 20% HP", description = "Two stationary 18,000-HP contingency crystals begin a 20-second rewrite. Each has a visible ward keyed to one of two nearby grounding stones. Two volunteers stand within 10 paces of their stones for 4 continuous seconds to expose the crystals; the rest destroy or control them."}, {label = "A favorable future", trigger = "Every 40 seconds outside rewrite", description = "A 12-second mark names one volunteer and a broad safe floor region. The marked player must end the warning in that region; other raiders can remain elsewhere."}}, abilities = {{name = "Break the contingency", summary = "At 75%, 45% and 20% HP", description = {"Two stationary 18,000-HP contingency crystals begin a 20-second rewrite. Each has a visible ward keyed to one of two nearby grounding stones. Two volunteers stand within 10 paces of their stones for 4 continuous seconds to expose the crystals; the rest destroy or control them.", "Success: Both crystals are destroyed or controlled at deadline; the rewrite fails and the boss loses 15% melee for 12 seconds.", "Failure: Each active crystal deals 550 magic damage to the raid 5 seconds apart and heals the boss 2% maximum HP, capped at 4% per cycle. All crystals become exposed after the first failed check."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "A favorable future", summary = "Every 40 seconds outside rewrite", description = {"A 12-second mark names one volunteer and a broad safe floor region. The marked player must end the warning in that region; other raiders can remain elsewhere.", "Success: The next contingency crystal starts with 3,000 less HP, once per crystal.", "Failure: The marked player takes 1,050 magic damage once; no teleport, charm or permanent character alteration."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"The raid leader asks Keeper Avel for this expedition with twelve to thirty-six eligible level-60 characters. The guide explains the leader's current attunement requirements. Combat is tuned for twenty-four to thirty-six characters."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the existing expedition through its guide or DZ Manager. Original instance and replay deadlines continue; returning does not create a new copy."}}}},
  ["ssratemple-emperor-ssraeshza-and-the-blood-seasonal"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 8 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold Emperor away from the Tithe refuge and maintain the existing guard control.", "During Judgment's Balance pick up two nearby Sentinels; no mandatory new tank swap or class-specific counter."}}, {id = "healer", label = "Healers", tips = {"Read the named Royal Vessel and cover its two or four 10%-HP ticks.", "Restore health before a possible 35%-HP pair failure; pulses are paused during the signature ward."}}, {id = "damage", label = "Damage dealers", tips = {"Balance the two Sentinel health pools and finish them within 12 seconds of one another.", "Use the shared assist call; do not require exact simultaneous kills."}}, {id = "everyone", label = "Everyone", tips = {"Give the Vessel the refuge; only the named character should enter.", "Speak to the Herald before activation to review each assignment and the current ritual stage."}}}, phases = {{label = "Blood of the Usurper", trigger = "Existing Blood kill and Emperor activation sequence.", description = "Defeat the Blood to begin the existing 180-300-second Emperor activation delay. The eight ordinary guards remain part of the encounter. During the delay, speak with the protected Herald for an explanation of the fixed Tithe refuge and paired-Sentinel rule. The Emperor retains his 3600-second reset cycle."}, {label = "Imperial Tithe", trigger = "First at 22 seconds, then 38 seconds after each completed resolution; below 10% repeat after 30 seconds.", description = "Name one non-tank as the Royal Vessel. Give 12 seconds to enter the fixed 18-unit Lealty refuge while everyone else stays outside its fixed 25-unit exclusion area. At impact, the Vessel begins four 10%-maximum-HP ticks at 0,2,4,6 seconds. Correct refuge attendance at impact ends the Tithe after the second tick; incorrect attendance retains all four. Any other player inside 25 units at impact takes one 20%-maximum-HP hit. Summoning is suppressed from warning through recovery; the boss and tank stay outside the refuge."}, {label = "Judgment's Balance", trigger = "At 80%,50% and 20% HP, once each per pull; queue behind an active Tithe.", description = "The Emperor becomes immune to all damage including existing DoT ticks, and creates exactly two Edict Sentinels: Voice of Divinity and Hand of Dominion. Both have the frozen support-add HP budget. They stand at two nearby fixed positions within ordinary tank/heal range. A 30-second total deadline begins at spawn; after the first Sentinel dies, the second must die within 12 seconds or before the total deadline, whichever comes first. Raid text announces both HP values every 5 seconds and the 12/6/3-second finishing countdown. Pause Tithe and all routine pulses throughout."}, {label = "Mortal Reign", trigger = "Routine pulse first at 14 seconds, then every 28 seconds; finale transition at 10% HP.", description = "The Emperor uses a scheduled 350-base-damage normal resistible magic pulse within 150 units. Ordinary boss melee and guard combat continue. At 10%, announce the final denial and shorten future Tithe cadence to 30 seconds, preserving the full 12-second warning."}}, abilities = {{name = "Blood of the Usurper", summary = "Existing Blood kill and Emperor activation sequence.", description = {"Defeat the Blood to begin the existing 180-300-second Emperor activation delay. The eight ordinary guards remain part of the encounter. During the delay, speak with the protected Herald for an explanation of the fixed Tithe refuge and paired-Sentinel rule. The Emperor retains his 3600-second reset cycle.", "Success: Signal-driven activation starts the seasonal fight once, with the standard guard behavior intact.", "Failure: A reset returns the Emperor to the correct inactive or active cycle state. The Blood's completed stage remains recognized; the Herald can explain the current stage before the next attempt."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Imperial Tithe", summary = "First at 22 seconds, then 38 seconds after each completed resolution; below 10% repeat after 30 seconds.", description = {"Name one non-tank as the Royal Vessel. Give 12 seconds to enter the fixed 18-unit Lealty refuge while everyone else stays outside its fixed 25-unit exclusion area. At impact, the Vessel begins four 10%-maximum-HP ticks at 0,2,4,6 seconds. Correct refuge attendance at impact ends the Tithe after the second tick; incorrect attendance retains all four. Any other player inside 25 units at impact takes one 20%-maximum-HP hit. Summoning is suppressed from warning through recovery; the boss and tank stay outside the refuge.", "Success: Correctly isolated Vessel takes two predictable ticks totaling 20% maximum HP, with no splash to properly positioned companions. After the Tithe finishes, provide 8 seconds recovery before another special assignment.", "Failure: Mispositioned Vessel receives the full four-tick 40% burden; other characters improperly sharing the refuge receive the single 20% hit. If the Vessel dies, disconnects, leaves the arena or disappears before impact, resolve one failed Tithe at the original 12-second deadline: request a 20%-maximum-HP raid hit, with no retarget or extra repeated raid ticks. If the Vessel is lost after Tithe ticks begin, remaining ticks stay bound to that original identity and are consumed at their original times; the attempt remains a recorded failure and cannot turn into a success."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Judgment's Balance", summary = "At 80%,50% and 20% HP, once each per pull; queue behind an active Tithe.", description = {"The Emperor becomes immune to all damage including existing DoT ticks, and creates exactly two Edict Sentinels: Voice of Divinity and Hand of Dominion. Both have the frozen support-add HP budget. They stand at two nearby fixed positions within ordinary tank/heal range. A 30-second total deadline begins at spawn; after the first Sentinel dies, the second must die within 12 seconds or before the total deadline, whichever comes first. Raid text announces both HP values every 5 seconds and the 12/6/3-second finishing countdown. Pause Tithe and all routine pulses throughout.", "Success: Kill the pair within the 12-second finishing window and 30-second total phase limit. Ward releases immediately and Emperor melee/spells stay paused for 8 seconds while his claim fractures.", "Failure: A missed pair window ends the phase immediately; a surviving Sentinel depops. Deal one 35%-maximum-HP hit to encounter participants and heal Emperor 3% of maximum HP once. If neither dies by 30 seconds, apply the same bounded failure. Ward always releases and the HP phase stays consumed even if the heal crosses its trigger."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}, {name = "Mortal Reign", summary = "Routine pulse first at 14 seconds, then every 28 seconds; finale transition at 10% HP.", description = {"The Emperor uses a scheduled 350-base-damage normal resistible magic pulse within 150 units. Ordinary boss melee and guard combat continue. At 10%, announce the final denial and shorten future Tithe cadence to 30 seconds, preserving the full 12-second warning.", "Success: Use resistance buffs and sustained healing between clearly scheduled assignments. End the encounter with the same learned personal-isolation rule.", "Failure: Normal routine damage plus the defined Tithe/pair penalties. Standard combat death remains possible, but no hidden forced kill."}, tags = {}, roles = {"tank", "healer", "damage", "everyone"}}}, sections = {{title = "Entry", paragraphs = {"An eligible seasonal group or raid leader requests this expedition from Theta Sigma in the public encounter zone. The accepted roster may contain three to seventy-two characters with current personal and server Luclin access."}, bullets = {}}, {title = "Wipes and return", paragraphs = {}, bullets = {"A wipe resets the unfinished encounter after ten seconds without a living engaged member in its arena. Completed encounters remain defeated.", "Follow named landmarks and text countdowns. Check every character's floor and position; pets and dead characters do not count for player assignments.", "Return to the same seasonal expedition through Theta Sigma. The existing three-day instance and two-day replay deadlines continue. Saved return is available only when that expedition has been registered successfully."}}}},
  ["unclaimed-dawn-court-3"] = {overview = {"Follow the named landmarks and the full text countdowns. Finish the current assignment before taking another.", "After an assignment resolves, allow at least 10 seconds of recovery. Scheduled routine pulses wait through assignments and recovery, then restart their full interval."}, roles = {{id = "tank", label = "Tanks", tips = {"Pick up the new aggressive signatory without treating projections as extra bosses."}}, {id = "healer", label = "Healers", tips = {"Prepare for separated failure pulses while lectern users retry."}}, {id = "damage", label = "Damage dealers", tips = {"Interrupt or control both countersigning clerks."}}, {id = "everyone", label = "Everyone", tips = {"Two volunteers use the announced lecterns in order, at least two seconds apart."}}}, phases = {{label = "Three signatures, one debt", trigger = "Whole encounter", description = "The aggressive lead actor owns one 540,000-HP encounter budget. At 75%, 50% and 25%, a different signatory takes over at the same current shared HP. Other actors are nonaggressive support; no trio of raid bosses or three full health bars is created."}, {label = "Revoke in the announced order", trigger = "Each transition", description = "The current signatory names two of three public objections. Two volunteers activate the corresponding lecterns in order within 18 seconds, with at least 2 seconds between them. No item click or class skill is required."}, {label = "The countersignature", trigger = "Every 35 seconds", description = "Two 16,000-HP clerks begin 12-second interruptible countersign casts. Interrupt, stun, mez or kill each."}}, abilities = {{name = "Three signatures, one debt", summary = "Whole encounter", description = {"The aggressive lead actor owns one 540,000-HP encounter budget. At 75%, 50% and 25%, a different signatory takes over at the same current shared HP. Other actors are nonaggressive support; no trio of raid bosses or three full health bars is created.",